import{_ as s,a0 as i,w as o,s as p,ao as u,I as r,x as e,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Linux 有問必答：如何在Perl中捕捉並處理信號 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在Perl中捕捉並處理信號 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在Perl中捕捉並處理信號 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在Perl中捕捉並處理信號 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140925 Linux FAQs with Answers--How to catch and handle a signal in Perl","title":"Linux 有問必答：如何在Perl中捕捉並處理信號","tag":"201410","desc":""},"relativePath":"201410/20140925 Linux FAQs with Answers--How to catch and handle a signal in Perl.md","filePath":"[post].md"}'),d={name:"201410/20140925 Linux FAQs with Answers--How to catch and handle a signal in Perl.md"};function m(T,t,x,h,g,f){const n=i("Link");return o(),p("div",null,[t[11]||(t[11]=u(`<h1 id="linux-有問必答-如何在perl中捕捉並處理信號" tabindex="-1">Linux 有問必答：如何在Perl中捕捉並處理信號 <a class="header-anchor" href="#linux-有問必答-如何在perl中捕捉並處理信號" aria-label="Permalink to “Linux 有問必答：如何在Perl中捕捉並處理信號”">​</a></h1><blockquote><p><strong>提問</strong>: 我需要通過使用Perl的自定義信號處理程序來處理一箇中斷信號。在一般情況下，我怎麼在Perl程序中捕獲並處理各種信號（如INT，TERM）？</p></blockquote><p>作為POSIX標準的異步通知機制，信號由操作系統發送給進程某個事件來通知它。當產生信號時，操作系統會中斷目標程序的執行，並且該信號被髮送到該程序的信號處理函數。可以定義和註冊自己的信號處理程序或使用默認的信號處理程序。</p><p>在Perl中，信號可以被捕獲，並由一個全局的%SIG哈希變量指定處理函數。這個%SIG哈希變量的鍵名是信號值，鍵值是對應的信號處理程序的引用。因此，如果你想為特定的信號定義自己的信號處理程序，你可以直接在%SIG中設置信號的哈希值。</p><p>下面是一個代碼段來處理使用自定義信號處理程序中斷（INT）和終止（TERM）的信號。</p><pre><code>$SIG{INT}  = \\&amp;signal_handler;
$SIG{TERM} = \\&amp;signal_handler;
 
sub signal_handler {
    print &quot;This is a custom signal handler\\n&quot;;
    die &quot;Caught a signal $!&quot;;
}
</code></pre><p><img src="https://farm4.staticflickr.com/3910/15141131060_f7958f20fb.jpg" alt=""></p><p>%SIG其他的可用的鍵值有&#39;IGNORE&#39;和&#39;DEFAULT&#39;。當所指定的鍵值是&#39;IGNORE&#39;（例如，$SIG{CHLD}=&#39;IGNORE&#39;）時，相應的信號將被忽略。指定&#39;DEFAULT&#39;的鍵值（例如，$SIG{HUP}=&#39;DEFAULT&#39;），意味着我們將使用一個（系統）默認的信號處理程序。</p><hr>`,9)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),a(n,{href:"http://ask.xmodulo.com/catch-handle-interrupt-signal-perl.html"},{default:l(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/catch-handle-interrupt-signal-perl.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:l(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:l(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:l(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const C=s(d,[["render",m]]);export{P as __pageData,C as default};
